algorithms.pseudocode:
function box_counting_dimension(points, scales):
    for each eps in scales:
        buckets <- empty set
        for each p in points:
            buckets.add(floor(p / eps))
        N[eps] <- |buckets|
    xs <- [log(1/eps) for eps in scales]
    ys <- [log(N[eps]) for eps in scales]
    return slope of least-squares line fitting (xs, ys)

function affine_image(c, a, points):
    assert c != 0          # else not invertible / not antilipschitz
    return [c * x + a for x in points]
